class Solution {
    public int removeElement(int[] nums, int val) {
        int write = 0;

        for (int read = 0; read < nums.length; read++) {
            if (nums[read] != val) {
                nums[write] = nums[read];
                write++;
            }
        }

        return write;
    }
}

class Solution {
    public int removeElement(int[] nums, int val) {
        int index = 0;
        int length = nums.length;

        while (index < length) {
            if (nums[index] == val) {
                nums[index] = nums[length - 1];
                length--;
            } else {
                index++;
            }
        }

        return length;
    }
}

class Solution {
    public int removeElement(int[] nums, int val) {
        int left = 0;
        int right = nums.length - 1;

        while (left <= right) {
            while (left <= right && nums[left] != val) {
                left++;
            }
            while (left <= right && nums[right] == val) {
                right--;
            }
            if (left < right) {
                int temp = nums[left];
                nums[left] = nums[right];
                nums[right] = temp;
                left++;
                right--;
            }
        }

        return right + 1;
    }
}

class Solution {
    public int removeElement(int[] nums, int val) {
        int[] count = new int[51];
        int kept = 0;

        for (int number : nums) {
            if (number != val) {
                count[number]++;
                kept++;
            }
        }

        int write = 0;
        for (int number = 0; number <= 50; number++) {
            while (count[number] > 0) {
                nums[write] = number;
                write++;
                count[number]--;
            }
        }

        return kept;
    }
}
